@dataclass(frozen=True)
class PageToken:
    offset: int
    top: int
    seam: int | None = None


def encode(token):
    data = {"o": token.offset, "t": token.top}
    if token.seam is not None:
        data["s"] = token.seam
    raw = json.dumps(data, separators=(",", ":")).encode()
    return base64.urlsafe_b64encode(raw).decode().rstrip("=")


def decode(text):
    padded = text + "=" * (-len(text) % 4)
    try:
        data = json.loads(base64.urlsafe_b64decode(padded.encode()))
        seam = int(data["s"]) if "s" in data else None
        token = PageToken(int(data["o"]), int(data["t"]), seam)
    except (binascii.Error, ValueError, KeyError, TypeError):
        raise InvalidRequest("malformed cursor") from None
    if token.offset < 0:
        raise InvalidRequest("malformed cursor")
    return token


def ensure_current(token, head_id, seam_id):
    """seam_id is the id now at position offset-1, or None if there is none."""
    if head_id != token.top or (token.offset > 0 and seam_id != token.seam):
        raise StaleCursor("the listing changed since the first page; start again")

